export function groupedSource(currency='USD'){
 const values=currency==='JPY'?[499,200,699,1200,500,4800,4800,8500,4800]:[4.99,2,6.99,12,5,48,48,85,48]
 const entries=values.map((price,i)=>({id:i+1,name:['Express delivery','Standard delivery','Priority dispatch','Vanilla add-on','Toppings add-on','Single box','Three-box offer','Seven-box offer','Hidden source box'][i],price,isSub:false,isOb:false,options:[{id:i+101,title:'Default',price:null,soldout:false}],variants:'{"variants":[]}'}))
 const html='<html><head><title>Grouped checkout fixture</title></head><body><main><h1>Your order choices</h1><div>'+[6,7,8].map(id=>'<label>Package '+id+'<input type=radio name=product-id_main_product value='+id+(id===8?' checked':'')+'></label>').join('')+'</div><div>'+[1,2,3].map(id=>'<label>Delivery '+id+'<input type=radio name=product-id_shipping_product value='+id+(id===1?' checked':'')+'></label>').join('')+'</div><label>Vanilla<input type=checkbox name=product-id value=4 checked></label><label>Toppings<input type=checkbox name=product-id value=5></label><div data-source="currentProduct"><input type=checkbox name=product-id value=9 style="display:none"></div><a href="#submit-step">Continue</a></main><script>window.FUNNEL='+JSON.stringify({id:77,currency_code:currency})+';window.STEP='+JSON.stringify({id:123,type:1,user_id:1,order_index:1})+';window.PRODUCTS='+JSON.stringify(entries)+';</script></body></html>'
 return{html,entries}
}
